      "path": "tools.grepai.grepai_1mcp_grepai_search",
      "description": "Semantic code search. Search your codebase using natural language queries. Returns the most relevant code chunks with file paths, line numbers, and similarity scores.

Examples:
- workspace-only mode: workspace='acme', path='src/'
- workspace + projects mode: workspace='acme', projects='backend,shared', path='api/'",
      "signature": "tools.grepai.grepai_1mcp_grepai_search({
  /** Return minimal output without content (default: false) */
  compact?: boolean,
  /** Output format: 'json' (default) or 'toon' (token-efficient) */
  format?: string,
  /** Maximum number of results to return (default: 10) */
  limit?: number,
  /**
   * Path prefix to filter results. When projects is set, path is relative to each selected project root (not workspace root). Examples: workspace-only path='src/' and workspace+projects path='MM32/src' or 'api/'.
   */
  path?: string,
  /** Comma-separated list of project names to search within workspace (requires workspace) */
  projects?: string,
  /** Natural language search query (e.g., 'user authentication flow', 'error handling middleware') */
  query: string,
  /**
   * Absolute project root path. When provided, the server will load configuration/index from this path (overrides server startup project). Optional.
   */
  root?: string,
  /** Workspace name for cross-project search (optional) */
  workspace?: string,
}): Promise<unknown>"
